#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn example() {
        let toks: Vec<Token> = Tokenizer::new("x1 = 42+y").collect();
        assert_eq!(
            toks,
            vec![Token::Ident("x1"), Token::Symbol('='), Token::Number("42"), Token::Symbol('+'), Token::Ident("y")]
        );
    }

    #[test]
    fn empty_and_whitespace() {
        assert_eq!(Tokenizer::new("").count(), 0);
        assert_eq!(Tokenizer::new("  \n\t ").count(), 0);
    }

    #[test]
    fn number_then_ident_and_underscores() {
        let toks: Vec<Token> = Tokenizer::new("123abc _foo_9(").collect();
        assert_eq!(
            toks,
            vec![Token::Number("123"), Token::Ident("abc"), Token::Ident("_foo_9"), Token::Symbol('(')]
        );
    }

    #[test]
    fn non_ascii_symbol() {
        let toks: Vec<Token> = Tokenizer::new("a→b").collect();
        assert_eq!(toks, vec![Token::Ident("a"), Token::Symbol('→'), Token::Ident("b")]);
    }

    #[test]
    fn tokens_outlive_tokenizer_and_point_into_input() {
        let src = String::from("let total = price * 3;");
        let ids = idents(&src);
        assert_eq!(ids, vec!["let", "total", "price"]);
        let base = src.as_ptr() as usize;
        let off = ids[1].as_ptr() as usize - base;
        assert_eq!(off, 4);
    }
}
